-- ════════════════════════════════════════════════════════════
-- SIT — Matriz de requisitoriedad (artículo + proveedor → documentos obligatorios)
-- Generado de: Matriz_Información Tecnica(1).xlsx, hoja "Base Resumida"
-- 7288 requisitos de 714 filas de la matriz.
-- Mapeo de columnas "(debe)" → idTipoDoc:
--   FT / Esp (debe)                                      → 1, 4
--   Ejemplo de Certificado de calidad (debe)             → 3
--   Hoja de Seguridad (debe)                             → 2
--   Carta Garantía de Calidad (debe)                     → 8
--   Carta Garantía Empaque Primario (debe)               → 8
--   Declaración de Alérgenos y Sensitivos                → 7
--   Tabla o Información Nutimental (debe)                → 5
--   Declaración de Pais de Origen del Producto (debe)    → 10
--   Aflatoxinas (debe)                                   → 11
--   Pesticidas (debe)                                    → 11
--   Metales Pesados Plomo (debe)                         → 11
--   Metales Pesados Arsenico (debe)                      → 11
--   Metales Pesados Cadmio (debe)                        → 11
--   Metales Pesados Mercurio (debe)                      → 11
--   Microbiología E. coli (debe)                         → 11
--   Microbiología Salmonella (debe)                      → 11
--   Carta de No Fraude Alimentario (debe)                → 9
--   Cuestionario Food Fraud (debe)                       → 12
--   Imagen (debe)                                        → 6
--   (omitida) Diagrama de Flujo del Proceso de Obtención (debe)
-- Idempotente: vuelve a correr sin duplicar (UNIQUE + NOT EXISTS).
-- ════════════════════════════════════════════════════════════

IF OBJECT_ID('sit_ap_requisitos', 'U') IS NULL
CREATE TABLE sit_ap_requisitos (
  id               INT IDENTITY(1,1) PRIMARY KEY,
  codigoArticulo   NVARCHAR(50)  NOT NULL,
  empresa          VARCHAR(10)   NOT NULL CHECK (empresa IN ('IAFSA', 'FDNC')),
  codigoProveedor  NVARCHAR(50)  NOT NULL,
  idTipoDoc        TINYINT       NOT NULL REFERENCES sit_tipos_documento(idTipoDoc),
  esObligatorio    BIT           NOT NULL DEFAULT 1,
  origen           NVARCHAR(30)  NOT NULL DEFAULT N'MATRIZ',
  fechaAlta        DATETIME      NOT NULL DEFAULT GETDATE(),
  CONSTRAINT UQ_sit_ap_requisitos UNIQUE (codigoArticulo, empresa, codigoProveedor, idTipoDoc)
)
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_sit_ap_requisitos_articulo')
  CREATE INDEX IX_sit_ap_requisitos_articulo ON sit_ap_requisitos(codigoArticulo, empresa)
GO

SET XACT_ABORT ON
SET NOCOUNT ON
BEGIN TRANSACTION

CREATE TABLE #req (codigoArticulo NVARCHAR(50), empresa VARCHAR(10), codigoProveedor NVARCHAR(50), idTipoDoc TINYINT, esObligatorio BIT)

