INSERT INTO sit_ap_requisitos (codigoArticulo, empresa, codigoProveedor, idTipoDoc, esObligatorio)
SELECT r.codigoArticulo, r.empresa, r.codigoProveedor, r.idTipoDoc, r.esObligatorio
FROM #req r
WHERE NOT EXISTS (
  SELECT 1 FROM sit_ap_requisitos x
  WHERE x.codigoArticulo = r.codigoArticulo AND x.empresa = r.empresa
    AND x.codigoProveedor = r.codigoProveedor AND x.idTipoDoc = r.idTipoDoc
)

SELECT @@ROWCOUNT AS requisitosInsertados

DROP TABLE #req
COMMIT TRANSACTION
